export function modelAuthorityProfile(modelId: string) {
  return modelAuthorityProfiles.find((row) => row.modelId === modelId);
}

export function authorityEditorialFor(model: Motorcycle) {
  const profile = modelAuthorityProfile(model.id);
  if (profile) return profile;
  return undefined;
}
